  return { doctor_id: s.doctor_id, doctor_name: s.doctor_name, department: s.department, date: s.date, date_display: s.date_display, start: s.start, start_display: s.start_display };
}
function describeSlots(slots) {
  const groups = new Map();
  for (const s of slots) {
    const k = s.doctor_name + '|' + s.date;
    if (!groups.has(k)) groups.set(k, { doc: s.doctor_name, date: s.date, times: [] });
    groups.get(k).times.push(s.start_display);
  }
  return Array.from(groups.values()).map(g => g.doc + ' on ' + niceDate(g.date) + ' at ' + g.times.join(', ')).join('; ');
}
function readSettings(rows) {
  const o = {};
  for (const r of rows) if (clean(r.key)) o[clean(r.key)] = clean(r.value);
  return o;
}
function intSetting(settings, key, def) {
  const v = parseInt(settings[key], 10);
  return isNaN(v) ? def : v;
}
function readHolidays(rows) {
  const set = new Set();
  for (const r of rows) {
    const m = clean(r.date).match(/\d{4}-\d{2}-\d{2}/);
    if (m) set.add(m[0]);
  }
  return set;
}

// ===== Extra helpers for the manage-appointment workflow =====
function digitsOnly(v) { // keeps only 0-9, converting Urdu and Arabic numerals first
  return clean(v)
    .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
    .replace(/\D/g, '');
}
function tail10(v) { return digitsOnly(v).slice(-10); }
function descField(desc, key) { // reads "key: value" lines from an event description
  const m = clean(desc).match(new RegExp('^\\s*' + key + ':\\s*(.+)$', 'mi'));
  return m ? m[1].trim() : '';
}
function toKarachi(ms) { // UTC milliseconds -> { date: 'YYYY-MM-DD', mins: minutes since midnight }
  const k = new Date(ms + TZ_OFFSET_MIN * 60000);
  return {
    date: k.getUTCFullYear() + '-' + pad(k.getUTCMonth() + 1) + '-' + pad(k.getUTCDate()),
    mins: k.getUTCHours() * 60 + k.getUTCMinutes()
  };
}

// Prepare Request: which action (from the URL), clean the inputs, and decide which days to read from Google Calendar
const input = $input.first().json;
const raw = input.body || {};
const query = input.query || {};
let action = clean(query.action || raw.action).toLowerCase();
if (['find', 'cancel', 'reschedule'].indexOf(action) < 0) action = '';

// Appointment ID: keep only the digits, then rebuild APT-YYYYMMDD-NNN (tolerates "A P T dash 2 0 2 6 ...")
const idDigits = digitsOnly(raw.appointment_id);
let appointment_id = '';
let idDate = '';
if (idDigits.length === 11) {
  const d = idDigits.slice(0, 4) + '-' + idDigits.slice(4, 6) + '-' + idDigits.slice(6, 8);
  if (isRealDate(d)) {
    appointment_id = 'APT-' + idDigits.slice(0, 8) + '-' + idDigits.slice(8);
    idDate = d;
  }
}
const phone = digitsOnly(raw.phone);
const newDate = clean(raw.new_date);
const newDateOk = isRealDate(newDate);
const newMin = parseHM(raw.new_start_time);

// The calendar window: from today to WINDOW_DAYS ahead (or the new date, if later).
// The appointment's own date is NOT used, because a reschedule moves the event but keeps the ID.
const WINDOW_DAYS = 45; // keep this at least max_advance_days + 1
const today = nowKarachi().date;
let hi = addDays(today, WINDOW_DAYS);
if (action === 'reschedule' && newDateOk && newDate > hi) hi = newDate;

return [{
  json: {
    action: action,
    appointment_id: appointment_id,
    id_date: idDate,
    phone: phone,
    new_date: newDateOk ? newDate : '',
    new_start: newMin === null ? '' : hm(newMin),
    timeMin: today + 'T00:00:00+05:00',
    timeMax: addDays(hi, 1) + 'T00:00:00+05:00'
  }
}];

